def solve(grid):
    """
    Transform the input grid according to the rule observed in the examples.
    The rule works with pairs of numbers (central, peripheral).  For each pair:
      * fill every empty cell that lies exactly between two peripheral cells in a
        straight line (horizontally or vertically) with the central number;
      * then make sure each central cell has at least one peripheral neighbour
        in each orthogonal direction: for every direction where the original
        grid contains at least one peripheral cell in that direction (same row
        for left/right, same column for up/down) we put a peripheral cell next
        to the central if the neighbour is empty.  If the central has no
        peripheral in its row at all we create peripheral cells on both sides,
        and similarly for the column when there is no peripheral in the column.
    The central / peripheral assignment is derived automatically:
        * the numbers that occur less frequently are the central ones;
        * for each central number the peripheral number is the other number
          that shares at least one row or column with the central (the one with
          the most such shared rows/columns).
    """
    if not grid:
        return grid
    h = len(grid)
    w = len(grid[0])

    # ----------------------------------------------------------------------
    # 1.  Determine the central / peripheral relationship.
    # ----------------------------------------------------------------------
    from collections import Counter, defaultdict

    freq = Counter()
    positions = defaultdict(list)          # value -> list of (r,c)
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v:
                freq[v] += 1
                positions[v].append((r,c))

    # central numbers are the least frequent ones
    min_freq = min(freq.values())
    central_numbers = [v for v, cnt in freq.items() if cnt == min_freq]

    # find a peripheral number for each central number
    peripheral = {}
    # pre‑compute rows / columns that contain each number
    rows_of = {v: {r for r,_ in positions[v]} for v in positions}
    cols_of = {v: {c for _,c in positions[v]} for v in positions}

    for cent in central_numbers:
        best_per = None
        best_score = -1
        cent_rows = rows_of[cent]
        cent_cols = cols_of[cent]
        for other, cnt in freq.items():
            if other == cent:
                continue
            # how many rows/columns do cent and 'other' share?
            shared_rows = len(cent_rows & rows_of[other])
            shared_cols = len(cent_cols & cols_of[other])
            score = shared_rows + shared_cols
            if score > best_score:
                best_score = score
                best_per = other
        if best_per is not None:
            peripheral[cent] = best_per

    # ----------------------------------------------------------------------
    # 2.  Helper structures built from the *original* grid (before any changes)
    # ----------------------------------------------------------------------
    # original peripheral positions for each pair
    orig_periph_pos = {}
    for cent, per in peripheral.items():
        # positions of the peripheral number in the original input
        orig_periph_pos[cent] = set(positions[per])

    # for fast lookup: for each row, which columns contain the peripheral number
    row_per_cols = {cent: defaultdict(set) for cent in peripheral}
    col_per_rows = {cent: defaultdict(set) for cent in peripheral}
    for cent, per in peripheral.items():
        for r,c in positions[per]:
            row_per_cols[cent][r].add(c)
            col_per_rows[cent][c].add(r)

    # ----------------------------------------------------------------------
    # 3.  Gap filling – place a central number in every empty cell that lies
    #     exactly between two peripheral cells in a straight line.
    # ----------------------------------------------------------------------
    for cent, per in peripheral.items():
        # horizontal gaps
        for r in range(h):
            for c in range(w-2):
                if grid[r][c] == per and grid[r][c+2] == per and grid[r][c+1] == 0:
                    grid[r][c+1] = cent
        # vertical gaps
        for c in range(w):
            for r in range(h-2):
                if grid[r][c] == per and grid[r+2][c] == per and grid[r+1][c] == 0:
                    grid[r+1][c] = cent

    # ----------------------------------------------------------------------
    # 4.  Add peripheral neighbours around every central cell (including the
    #     ones that were just inserted).
    # ----------------------------------------------------------------------
    # we scan the whole grid again; every cell that now contains a central
    # number will be processed.
    for r in range(h):
        for c in range(w):
            cent = grid[r][c]
            if cent not in peripheral:
                continue
            per = peripheral[cent]

            # existence of peripheral cells in the four directions (based on the
            # original grid, not on the cells we may have added just now)
            row_set = row_per_cols[cent][r]
            col_set = col_per_rows[cent][c]

            left_exists  = any(col < c for col in row_set)
            right_exists = any(col > c for col in row_set)
            up_exists    = any(row < r for row in col_set)
            down_exists  = any(row > r for row in col_set)

            # ----- horizontal ------------------------------------------------
            if left_exists:
                if c-1 >= 0 and grid[r][c-1] == 0:
                    grid[r][c-1] = per
            if right_exists:
                if c+1 < w and grid[r][c+1] == 0:
                    grid[r][c+1] = per
            if not left_exists and not right_exists:
                # create peripheral on both sides
                if c-1 >= 0 and grid[r][c-1] == 0:
                    grid[r][c-1] = per
                if c+1 < w and grid[r][c+1] == 0:
                    grid[r][c+1] = per

            # ----- vertical --------------------------------------------------
            # decide whether we need to add vertical neighbours
            if not up_exists and not down_exists:
                # column completely empty – add on both sides when the
                # horizontal line was also empty, otherwise add only the up side
                if not left_exists and not right_exists:
                    if r-1 >= 0 and grid[r-1][c] == 0:
                        grid[r-1][c] = per
                    if r+1 < h and grid[r+1][c] == 0:
                        grid[r+1][c] = per
                else:
                    if r-1 >= 0 and grid[r-1][c] == 0:
                        grid[r-1][c] = per
            else:
                if up_exists:
                    if r-1 >= 0 and grid[r-1][c] == 0:
                        grid[r-1][c] = per
                elif down_exists:
                    if r+1 < h and grid[r+1][c] == 0:
                        grid[r+1][c] = per

    return grid

